python
def fixedPanelsTotalReceipt(readings, k):
    a=readings
    out=[]
    s=0
    for i,x in enumerate(a):
        s+=x
        if i>=k: s-=a[i-k]
        if i>=k-1: out.append(s)
    return sum(out)


